if (values.empty()) throw std::invalid_argument("Median needs at least one value");
std::vector<double> sorted(values.begin(), values.end());
std::sort(sorted.begin(), sorted.end());
std::size_t middle = sorted.size() / 2;
return sorted.size() % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;

languages.rust:
if values.is_empty() { panic!("Median needs at least one value"); }
let mut sorted = values.clone();
sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
let middle = sorted.len() / 2;
return if sorted.len() % 2 == 1 { sorted[middle] } else { (sorted[middle - 1] + sorted[middle]) / 2.0 };

